package com.northstar.crm.service;
import com.northstar.crm.domain.*;import com.northstar.crm.repo.NotificationRepository;import com.northstar.crm.security.ActorResolver;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class NotificationService {private final NotificationRepository notifications;private final ActorResolver actors;public NotificationService(NotificationRepository n,ActorResolver a){notifications=n;actors=a;}@Transactional public void send(UUID user,String title,String message,String route){notifications.save(new Notification(user,title,message,route));}@Transactional(readOnly=true)public List<Notification> mine(){return notifications.findTop30ByUserIdOrderByCreatedAtDesc(actors.current().getId());}@Transactional(readOnly=true)public long unread(){return notifications.countByUserIdAndReadFlagFalse(actors.current().getId());}@Transactional public void markRead(UUID id){var actor=actors.current();var n=notifications.findById(id).orElseThrow();if(!n.getUserId().equals(actor.getId()))throw new org.springframework.security.access.AccessDeniedException("Not your notification");n.markRead();}}
